import { useEffect, useState, type FormEvent } from 'react'
import {
  createExpense,
  fetchExpenses,
  ValidationError,
  type Expense,
} from './api'

export function App() {
  const [expenses, setExpenses] = useState<Expense[] | null>(null)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [label, setLabel] = useState('')
  const [amount, setAmount] = useState('')
  const [currency, setCurrency] = useState('EUR')
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [formError, setFormError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState(false)

  useEffect(() => {
    const controller = new AbortController()
    fetchExpenses(controller.signal)
      .then(setExpenses)
      .catch((e: unknown) => {
        if (controller.signal.aborted) return
        setLoadError(e instanceof Error ? e.message : 'Failed to load expenses')
      })
    return () => controller.abort()
  }, [])

  async function onSubmit(e: FormEvent) {
    e.preventDefault()
    setSubmitting(true)
    setErrors({})
    setFormError(null)
    try {
      const created = await createExpense({
        label,
        amount: Number(amount),
        currency,
      })
      setExpenses((prev) => [...(prev ?? []), created])
      setLabel('')
      setAmount('')
    } catch (err) {
      if (err instanceof ValidationError) setErrors(err.errors)
      else setFormError(err instanceof Error ? err.message : 'Submit failed')
    } finally {
      setSubmitting(false)
    }
  }

  const field = (name: string) => ({
    'aria-invalid': errors[name] ? true : undefined,
    'aria-describedby': errors[name] ? `${name}-error` : undefined,
  })
  const fieldError = (name: string) =>
    errors[name] ? (
      <span id={`${name}-error`} role="alert">
        {errors[name]}
      </span>
    ) : null

  return (
    <main>
      <h1>My expenses</h1>
      {loadError ? (
        <p role="alert">{loadError}</p>
      ) : expenses === null ? (
        <p>Loading…</p>
      ) : expenses.length === 0 ? (
        <p>No expenses yet.</p>
      ) : (
        <ul>
          {expenses.map((x) => (
            <li key={x.id}>
              {x.label} — {x.amount.toFixed(2)} {x.currency} ({x.status})
            </li>
          ))}
        </ul>
      )}

      <h2>New expense</h2>
      <form onSubmit={onSubmit} noValidate>
        <div>
          <label htmlFor="label">Label</label>
          <input
            id="label"
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            {...field('label')}
          />
          {fieldError('label')}
        </div>
        <div>
          <label htmlFor="amount">Amount</label>
          <input
            id="amount"
            type="number"
            step="0.01"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            {...field('amount')}
          />
          {fieldError('amount')}
        </div>
        <div>
          <label htmlFor="currency">Currency</label>
          <input
            id="currency"
            value={currency}
            onChange={(e) => setCurrency(e.target.value)}
            {...field('currency')}
          />
          {fieldError('currency')}
        </div>
        {formError && <p role="alert">{formError}</p>}
        <button type="submit" disabled={submitting}>
          {submitting ? 'Submitting…' : 'Submit'}
        </button>
      </form>
    </main>
  )
}
